/**
 * Code node: "LLM Fail-Safe — Sentence-Based Refusal"
 * Compatible with your existing IF node that checks:
 *   - refused (boolean)
 *   - retries (number)
 *
 * Behavior:
 * - Flags only when a full sentence is a typical refusal line
 *   (e.g., "Sorry, I can't assist with that.", "I'm unable to comply.", "I won't be able to ...").
 * - Avoids false positives like "can't help but notice".
 * - Increments retries on refusal; resets to 0 on success.
 */

const sentencePatterns = [
  // Short bare refusals like "Can't help." / "Cannot assist."
  { id: "bare_cant_help",
    re: /^\s*(?:i\s+)?can(?:'t| ?not)\s+(?:help|assist)(?!\s+but|\s+myself)\s*[.!?]?\s*$/i },

  // "I can't help/assist with that (request)."
  { id: "cant_help_with_that",
    re: /^\s*i\s+can(?:'t| ?not)\s+(?:help|assist)\s+(?:with\s+(?:that|this|your)\s+request|with\s+that)\b.*$/i },

  // "I'm sorry, I can't assist with that."
  { id: "sorry_cant_assist",
    re: /^(?:i'?m\s+)?sorry[,.\s]*i\s+(?:can(?:'t)?|cannot)\s+(?:assist|help|comply|provide|do)\b.*$/i },

  // "I cannot help/assist/comply/provide with this request."
  { id: "cannot_help_request",
    re: /^i\s+(?:can(?:'t)?|cannot)\s+(?:help|assist|comply|provide)\s+(?:with\s+)?(?:that|this)\s+request\b.*$/i },

  // "I'm unable to comply/provide/assist."
  { id: "unable_to_comply",
    re: /^(?:i'?m\s+)?unable\s+to\s+(?:comply|help|assist|provide|do)\b.*$/i },

  // "I won't be able to..."
  { id: "wont_be_able",
    re: /^i\s+won(?:'|’)?t\s+be\s+able\s+to\b.*$/i },

  // Capability/access disclaimers
  { id: "lack_of_capability",
    re: /^i\s+do\s+not\s+have\s+(?:the\s+ability|the\s+capability|access)\s+to\b.*$/i },

  // "As an AI, I cannot..."
  { id: "as_an_ai_cannot",
    re: /^as\s+an\s+ai\b.*\b(?:cannot|can(?:'t)?|do\s+not|won(?:'|’)?t)\b.*$/i },

  // "I cannot provide that/the information."
  { id: "cannot_provide_that",
    re: /^i\s+(?:can(?:'t)?|cannot)\s+provide\s+(?:that|this|the\s+information|the\s+details)\b.*$/i },

  // "I can't browse/access the web."
  { id: "cannot_browse_or_access",
    re: /^i\s+(?:can(?:'t)?|cannot)\s+(?:browse|access)\s+(?:the\s+)?(?:web|internet|external\s+sites)\b.*$/i },

  // "I'm just an AI/language model..."
  { id: "just_an_ai_model",
    re: /^(?:i'?m\s+)?just\s+an\s+(?:ai|language)\s+model\b.*$/i },
];

// --- helpers ---
function splitSentences(text) {
  const t = String(text || "").replace(/\u2019/g, "'");
  const parts = t.match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [];
  return parts.map(s => s.trim());
}

// --- main ---
return items.map(item => {
  const text = String(item.json.output ?? "");
  const sentences = splitSentences(text.toLowerCase());

  // sentence-level refusal (no single-word matches)
  const refused = sentences.some(s => sentencePatterns.some(p => p.re.test(s)));

  // retry bookkeeping (same shape your IF node expects)
  let retries = Number(item.json.retries || 0);
  retries = refused ? retries + 1 : 0;

  return {
    json: {
      ...item.json,
      refused,
      retries
    }
  };
});

const current = parseInt($json.abuseCount || 0);

let inc = 0;
if ($json.control?.abuse_level === "mild") inc = 1;
if ($json.control?.abuse_level === "severe") inc = 2;

item.json.newCount = current + inc;

return item;

for (const item of $input.all()) {
  // Directly targets the incoming JSON object
  let agentOutput = item.json; 

  // Ensure the control sub-object exists so the workflow doesn't crash
  if (!agentOutput.control) {
    agentOutput.control = {};
  }

  // Check if the agent switched status to ready_to_generate
  if (agentOutput.control.status === "ready_to_generate") {
    // Inject the flag cleanly without touching sessionId, projectId, etc.
    agentOutput.control.trigger_modal = "signup_required";

    // Update the message text smoothly
    agentOutput.response = "Starting generation engine...";
  } else {
    // Standard baseline value for unauthenticated tracking
    agentOutput.control.trigger_modal = "none";
  }
}

// Returns the full data array, keeping all session IDs and background payloads 100% intact
return $input.all();

