}

const concepts = [payloads.prompt_1, payloads.prompt_2];

// 3) Build fluid api_payloads for the loop AND pass the response out cleanly
const items = concepts.map((concept, idx) => {
  if (!concept || typeof concept.final_prompt !== 'string') {
    throw new Error(`Concept at index ${idx} is missing 'final_prompt'.`);
  }

  return {
    json: {
      // It sits safely out here, perfectly separated from the api_payload!
