// 1. Extract required fields from webhook body safely
const inputItem = $input.first();
const body = inputItem.json.body || {};

const projectId = body.projectId;
const userId = body.userId;
const message = body.message;
const attachedImage = body.attachedImage; // <-- NY: Hämtar bildlänken från Cloudinary
const imageUsage = body.imageUsage;       // <-- NY: Hämtar "inspiration" eller "reference"

// 2. Clean / normalize message text strings
const cleanText = String(message || "")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

// 3. Flag if they are a guest based on userId being null/empty
const isGuest = (!userId || userId === "null" || userId === "undefined");

// 4. Build output object
const outputItem = {
  json: {
    isGuest: isGuest,
    projectId: projectId,
    userId: userId,
    message: cleanText,
    attachedImage: attachedImage || null,
    imageUsage: imageUsage || null
  }
};

// 5. If binary file exists, safely bring it forward; if not, it stays empty safely
if (inputItem.binary) {
  outputItem.binary = inputItem.binary;
}

return [outputItem];

// Parse the incoming AI JSON string
let rawOutput = JSON.parse($input.item.json.output);

// Safely grab the project ID from the root input
let projectId = $input.item.json.projectId;

// Get the actual image data from the webhook (frontend)
let attachedImage = $input.item.json.attachedImage || "";
let imageUsage = $input.item.json.imageUsage || "N/A";

// Detect where meta is located (handles old nested layout AND new root layout)
let sourceMeta = rawOutput.meta || rawOutput.summary?.meta || {};

// Rebuild the exact shape your Redis node expects under the "summary" key
let updatedSummary = {
  brand: rawOutput.summary?.brand || {},
  design: rawOutput.summary?.design || {},
  asset: rawOutput.summary?.asset || {},
  output: rawOutput.summary?.output || {},
  meta: {
    confidence: sourceMeta.confidence || "N/A",
    // Use webhook values if available, fallback to AI's values
    image_intent: imageUsage !== "N/A" ? imageUsage : (sourceMeta.image_intent || "N/A"),
    attached_reference_url: attachedImage || sourceMeta.attached_reference_url || "N/A",
    design_brief_1: "N/A", // Forced reset
    design_brief_2: "N/A"  // Forced reset
  }
};

// Return everything to the next node
return {
  json: {
    projectId: projectId, // Keeps your Redis key from saying 'undefined'
    summary: updatedSummary
  }
};

const item = $input.first().json;

// Extract image fields – try top-level, then meta, then summary.meta
const imageUsage = item.imageUsage 
  || item.image_intent 
  || item.imageIntent 
  || item.meta?.image_intent 
  || item.summary?.meta?.image_intent 
  || "none";

const attachedImage = item.attachedImage 
  || item.attached_reference_url 
  || item.attachedReferenceUrl 
  || item.meta?.attached_reference_url 
  || item.summary?.meta?.attached_reference_url 
  || "";

// Extract reference_mode – from meta or summary.meta
const referenceMode = item.meta?.reference_mode 
  || item.summary?.meta?.reference_mode 
  || "N/A";

// Keep the rest of the summary and meta
const rawSummary = item.summary || item.Summary || {};
const rootMeta = item.meta || {};
const summaryMeta = rawSummary.meta || {};

const getRealValue = (...values) => {
  for (const val of values) {
    if (val && val !== "N/A") return val;
  }
  return "N/A";
};

const designBrief1 = getRealValue(item.design_brief_1, rootMeta.design_brief_1, summaryMeta.design_brief_1);
const designBrief2 = getRealValue(item.design_brief_2, rootMeta.design_brief_2, summaryMeta.design_brief_2);

// Build the summary object, including the image fields so they travel with the brand data
const summary = {
  brand: rawSummary.brand || {},
  design: rawSummary.design || {},
  asset: rawSummary.asset || {},
  output: rawSummary.output || {},
  image_intent: imageUsage,
  attached_reference_url: attachedImage,
  reference_mode: referenceMode, // 👈 added
};

return [
  {
    json: {
      status: item.control?.status || "ready_to_generate",
      projectId: item.projectId,
      imageUsage: imageUsage,
      attachedImage: attachedImage,
      referenceMode: referenceMode, // 👈 added at top level
      summary: summary,
      design_brief_1: designBrief1,
      design_brief_2: designBrief2
    }
  }
];

// Get the first item (the data passed from the previous node)
const item = $input.first().json;

// Build a clean object – this will be automatically JSON‑stringified by n8n
const payload = {
  text: item.response || "",
  trigger_modal: item.control?.trigger_modal || "none",
  projectId: item.projectId || ""
};

// Return as a single JSON object
return [ { json: payload } ];

// 1. Get all incoming items
const items = $input.all();

let textResponse = "Here are your generated concepts.";
let projectId = null;

// 2. Loop through every single item to extract the scattered values
for (const item of items) {
  const data = item.json;

  if (!data) continue;

  // Grab the projectId if this item has it
  if (data.projectId) {
    projectId = data.projectId;
  }

  // Grab the text response if this item has it
  if (data.agent_response) {
    textResponse = data.agent_response;
  }
}

// 3. Extract all available scene titles from the items
const sceneTitles = items.map(item => item.json?.scene_title).filter(Boolean);

// 4. Pull the generated image URLs from workflow memory state
const storedPhotos = globalThis.workflowState?.photos || [];
const imageUrls = storedPhotos.map(photo => photo.url);

// Fallback: Check local item keys if memory state is empty
if (imageUrls.length === 0) {
  items.forEach(item => {
    if (item.json?.imageUrl) imageUrls.push(item.json.imageUrl);
  });
}

// 5. Package and return the clean object
return [{
  json: {
    projectId: projectId,
    response: textResponse,
    concept_1_title: sceneTitles[0] || "Concept 1",
    concept_1_url: imageUrls[0] || null,
    concept_2_title: sceneTitles[1] || "Concept 2",
    concept_2_url: imageUrls[1] || null
  }
}];

// Get all input items (handles arrays)
const items = $input.all();

const results = items.map(item => {
  const data = item.json;

  // Start with root values
  let attachedImage = data.attachedImage ?? null;
  let imageUsage = data.imageUsage ?? null;

  // Helper: extract from meta, but only if current value is not already set
  const extractFromMeta = (obj) => {
    if (obj && typeof obj === 'object') {
      // Only set if current is null/empty and the found value is valid (not "N/A")
      if (!attachedImage || attachedImage === "N/A") {
        if (obj.attached_reference_url && obj.attached_reference_url !== "N/A") {
          attachedImage = obj.attached_reference_url;
        }
      }
      if (!imageUsage || imageUsage === "N/A") {
        if (obj.image_intent && obj.image_intent !== "N/A") {
          imageUsage = obj.image_intent;
        }
      }
    }
  };

  // -------- STRATEGY 1: If 'summary' is a JSON string --------
  if (data.summary && typeof data.summary === 'string') {
    try {
      const parsed = JSON.parse(data.summary);
      if (parsed.meta) extractFromMeta(parsed.meta);
      if (parsed.attached_reference_url && parsed.attached_reference_url !== "N/A") {
        attachedImage = parsed.attached_reference_url;
      }
      if (parsed.image_intent && parsed.image_intent !== "N/A") {
        imageUsage = parsed.image_intent;
      }
    } catch (e) {}
  }

  // -------- STRATEGY 2: If 'summary' is already an object --------
  if (data.summary && typeof data.summary === 'object') {
    if (data.summary.meta) extractFromMeta(data.summary.meta);
    if (data.summary.attached_reference_url && data.summary.attached_reference_url !== "N/A") {
      attachedImage = data.summary.attached_reference_url;
    }
    if (data.summary.image_intent && data.summary.image_intent !== "N/A") {
      imageUsage = data.summary.image_intent;
    }
  }

  // -------- STRATEGY 3: Look for root-level 'meta' --------
  if (data.meta) extractFromMeta(data.meta);

  // -------- STRATEGY 4: Look for 'meta' inside 'asset' --------
  if (data.asset && data.asset.meta) extractFromMeta(data.asset.meta);

  // -------- STRATEGY 5: Direct root fields (already at start) --------
  // We already set them at the beginning, so we don't need to override again.

  // Return everything untouched, only update the two fields
  return {
    json: {
      ...data,
      attachedImage,
      imageUsage
    }
  };
});

return results;
